from pathlib import Path

for article in articles:
    content_html = []
    for block in article["content"]:
        if block["type"] == "p":
            content_html.append(f"<p>{block['text']}</p>")
        elif block["type"] == "h2":
            content_html.append(f"<h2>{block['text']}</h2>")
    tags_html = "".join(f"<span class=\"tag\">{tag}</span>" for tag in article["tags"])
    share_text = quote(article["title"])
    html = template.format(
        title=article["title"],
        description=article["description"],
        og_description=article["og_description"],
        filename=article["filename"],
        image_og=article["image"],
        image=article["image"],
        image_alt=article["image_alt"],
        date=article["date"],
        author=article["author"],
        category=article["category"],
        category_url=article["category_url"],
        content_html="\n      ".join(content_html),
        tags_html=tags_html,
        share_text=share_text
    )
    Path(article["filename"]).write_text(html, encoding="utf-8")
